SET search_path=main,pg_catalog;
CREATE TABLE approved_option_lifecycle_events(event_uid VARCHAR PRIMARY KEY, event_type VARCHAR NOT NULL, source_broker VARCHAR NOT NULL, source_account_id VARCHAR NOT NULL, currency VARCHAR NOT NULL, effective_at_utc VARCHAR NOT NULL, option_instrument_key VARCHAR NOT NULL, predecessor_direction VARCHAR NOT NULL, contracts DECIMAL(38,10) NOT NULL, event_commission DECIMAL(38,10) NOT NULL, event_fees DECIMAL(38,10) NOT NULL, evidence_status VARCHAR NOT NULL, successor_action VARCHAR, successor_position_effect VARCHAR, successor_symbol VARCHAR, successor_quantity DECIMAL(38,10), strike_cash_amount DECIMAL(38,10), reviewed_at_utc VARCHAR NOT NULL, review_source VARCHAR NOT NULL, instruction_path VARCHAR NOT NULL);
