CREATE TABLE approved_option_lifecycle_source_legs(event_uid VARCHAR, event_leg_uid VARCHAR, PRIMARY KEY(event_uid, event_leg_uid));
CREATE TABLE broker_position_snapshot_records(snapshot_uid VARCHAR, instrument_key VARCHAR, asset_class VARCHAR NOT NULL, market_scope VARCHAR NOT NULL, currency VARCHAR NOT NULL, symbol VARCHAR, underlying_symbol VARCHAR, expiry DATE, option_right VARCHAR, strike DECIMAL(38,10), multiplier DECIMAL(38,10), provider_position_id VARCHAR, quantity DECIMAL(38,10) NOT NULL, broker_average_cost DECIMAL(38,13), broker_market_value DECIMAL(38,10), broker_unrealized_pnl DECIMAL(38,13), broker_tax_lot_average_price DECIMAL(38,13), PRIMARY KEY(snapshot_uid, instrument_key));
