CREATE TABLE import_runs(import_run_id VARCHAR PRIMARY KEY, source_type VARCHAR NOT NULL, source_path VARCHAR, asof_date DATE, imported_at TIMESTAMP NOT NULL, row_count INTEGER NOT NULL, status VARCHAR NOT NULL, notes VARCHAR);
CREATE TABLE journal_entries(entry_uid UUID DEFAULT(gen_random_uuid()) PRIMARY KEY, created_at TIMESTAMP NOT NULL, created_source VARCHAR NOT NULL, CHECK((created_source IN ('streamlit', 'import', 'operator', 'api'))));
CREATE TABLE journal_goals(goal_uid UUID DEFAULT(gen_random_uuid()) PRIMARY KEY, "name" VARCHAR NOT NULL, normalized_name VARCHAR NOT NULL UNIQUE, description VARCHAR, cadence VARCHAR NOT NULL, target_count INTEGER NOT NULL, status VARCHAR NOT NULL, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, CHECK((cadence IN ('weekly', 'monthly'))), CHECK((target_count > 0)), CHECK((status IN ('active', 'archived'))));
CREATE TABLE journal_habits(habit_uid UUID DEFAULT(gen_random_uuid()) PRIMARY KEY, "name" VARCHAR NOT NULL, normalized_name VARCHAR NOT NULL UNIQUE, description VARCHAR, cadence VARCHAR NOT NULL, target_count INTEGER NOT NULL, status VARCHAR NOT NULL, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, CHECK((cadence IN ('daily', 'weekly', 'monthly'))), CHECK((target_count > 0)), CHECK((status IN ('active', 'archived'))));
CREATE TABLE journal_reviews(review_uid UUID DEFAULT(gen_random_uuid()) PRIMARY KEY, episode_uid VARCHAR NOT NULL, review_status VARCHAR NOT NULL, setup_quality VARCHAR NOT NULL, entry_reason VARCHAR, notes VARCHAR, supersedes_review_uid UUID UNIQUE, "source" VARCHAR NOT NULL, created_at TIMESTAMP NOT NULL, FOREIGN KEY (supersedes_review_uid) REFERENCES journal_reviews(review_uid) DEFERRABLE INITIALLY IMMEDIATE, CHECK((review_status IN ('unreviewed', 'needs_review', 'mistake_review', 'reviewed'))), CHECK((setup_quality IN ('unknown', 'good', 'acceptable', 'poor', 'mistake'))), CHECK(("source" IN ('legacy_backfill', 'streamlit', 'import', 'api'))));
CREATE TABLE journal_strategies(strategy_uid UUID DEFAULT(gen_random_uuid()) PRIMARY KEY, "name" VARCHAR NOT NULL, normalized_name VARCHAR NOT NULL UNIQUE, description VARCHAR, status VARCHAR NOT NULL, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, CHECK((status IN ('active', 'archived'))));
