CREATE TABLE phase1_journal_execution_projection_runs(projection_uid VARCHAR PRIMARY KEY, contract_version VARCHAR NOT NULL, materialization_uid VARCHAR NOT NULL UNIQUE, episode_count INTEGER NOT NULL, instrument_count INTEGER NOT NULL, execution_count INTEGER NOT NULL, schwab_net_amount_match_count INTEGER NOT NULL, schwab_net_amount_mismatch_count INTEGER NOT NULL, result_fingerprint VARCHAR NOT NULL UNIQUE, projected_at TIMESTAMP NOT NULL, FOREIGN KEY (materialization_uid) REFERENCES phase1_journal_materialization_runs(materialization_uid) DEFERRABLE INITIALLY IMMEDIATE, CHECK((contract_version = 'onejournal.phase1-journal-execution-projection.v1')), CHECK(((episode_count >= 0) AND (instrument_count >= 0) AND (execution_count >= 0) AND (schwab_net_amount_match_count >= 0) AND (schwab_net_amount_mismatch_count = 0) AND (execution_count = schwab_net_amount_match_count))), CHECK((length(result_fingerprint) = 64)));
CREATE TABLE phase1_journal_history_revision_episode_fills(revision_uid VARCHAR, episode_uid VARCHAR, leg_index INTEGER, fill_uid VARCHAR NOT NULL, source_record_fingerprint VARCHAR NOT NULL, PRIMARY KEY(revision_uid, episode_uid, leg_index), UNIQUE(revision_uid, fill_uid), FOREIGN KEY (revision_uid, episode_uid) REFERENCES phase1_journal_history_revision_episodes(revision_uid, episode_uid) DEFERRABLE INITIALLY IMMEDIATE, FOREIGN KEY (fill_uid) REFERENCES normalized_fills(fill_uid) DEFERRABLE INITIALLY IMMEDIATE, CHECK(((leg_index > 0) AND (length(source_record_fingerprint) = 64))));
CREATE TABLE phase1_journal_history_revision_executions(revision_uid VARCHAR, episode_uid VARCHAR, execution_index INTEGER, execution_uid VARCHAR NOT NULL, fill_uid VARCHAR NOT NULL, instrument_uid VARCHAR NOT NULL, filled_at_utc VARCHAR NOT NULL, side VARCHAR NOT NULL, quantity DECIMAL(38,10) NOT NULL, fill_price DECIMAL(38,10) NOT NULL, multiplier DECIMAL(38,10) NOT NULL, commission DECIMAL(38,10) NOT NULL, fees DECIMAL(38,10) NOT NULL, currency VARCHAR NOT NULL, schwab_net_cash_movement DECIMAL(38,10) NOT NULL, calculated_net_cash_movement DECIMAL(38,10) NOT NULL, net_amount_reconciled BOOLEAN NOT NULL, execution_projection_fingerprint VARCHAR NOT NULL, PRIMARY KEY(revision_uid, episode_uid, execution_index), UNIQUE(revision_uid, fill_uid), FOREIGN KEY (revision_uid, episode_uid) REFERENCES phase1_journal_history_revision_episodes(revision_uid, episode_uid) DEFERRABLE INITIALLY IMMEDIATE, FOREIGN KEY (fill_uid) REFERENCES normalized_fills(fill_uid) DEFERRABLE INITIALLY IMMEDIATE, CHECK(((execution_index > 0) AND (quantity > 0) AND (multiplier > 0))), CHECK(((net_amount_reconciled = CAST('t' AS BOOLEAN)) AND (schwab_net_cash_movement = calculated_net_cash_movement))), CHECK((length(execution_projection_fingerprint) = 64)));
CREATE TABLE phase1_journal_history_revision_instruments(revision_uid VARCHAR, episode_uid VARCHAR, instrument_index INTEGER, instrument_uid VARCHAR NOT NULL, asset_class VARCHAR NOT NULL, symbol VARCHAR NOT NULL, underlying_symbol VARCHAR, option_type VARCHAR, expiry DATE, strike DECIMAL(38,10), multiplier DECIMAL(38,10), currency VARCHAR NOT NULL, opening_direction VARCHAR, execution_count INTEGER NOT NULL, buy_quantity DECIMAL(38,10) NOT NULL, sell_quantity DECIMAL(38,10) NOT NULL, captured_quantity_delta DECIMAL(38,10) NOT NULL, instrument_projection_fingerprint VARCHAR NOT NULL, PRIMARY KEY(revision_uid, episode_uid, instrument_index), UNIQUE(revision_uid, episode_uid, instrument_uid), FOREIGN KEY (revision_uid, episode_uid) REFERENCES phase1_journal_history_revision_episodes(revision_uid, episode_uid) DEFERRABLE INITIALLY IMMEDIATE, CHECK(((instrument_index > 0) AND (execution_count > 0))), CHECK(((opening_direction IS NULL) OR (opening_direction IN ('LONG', 'SHORT')))), CHECK((length(instrument_projection_fingerprint) = 64)));
CREATE TABLE phase1_journal_materialized_episodes(materialization_uid VARCHAR, episode_uid VARCHAR, scope_uid VARCHAR NOT NULL, lifecycle_quality VARCHAR NOT NULL, reason_code VARCHAR, source_fill_count INTEGER NOT NULL, episode_fingerprint VARCHAR NOT NULL, PRIMARY KEY(materialization_uid, episode_uid), FOREIGN KEY (materialization_uid) REFERENCES phase1_journal_materialization_runs(materialization_uid) DEFERRABLE INITIALLY IMMEDIATE, FOREIGN KEY (episode_uid) REFERENCES trade_episodes(episode_uid) DEFERRABLE INITIALLY IMMEDIATE, CHECK((lifecycle_quality IN ('resolved', 'review_required'))), CHECK((((lifecycle_quality = 'resolved') AND (reason_code IS NULL)) OR ((lifecycle_quality = 'review_required') AND (reason_code IS NOT NULL)))), CHECK((source_fill_count > 0)), CHECK((length(episode_fingerprint) = 64)));
CREATE TABLE phase1_journal_materialized_fills(materialization_uid VARCHAR, fill_uid VARCHAR, source_record_fingerprint VARCHAR NOT NULL, PRIMARY KEY(materialization_uid, fill_uid), FOREIGN KEY (materialization_uid) REFERENCES phase1_journal_materialization_runs(materialization_uid) DEFERRABLE INITIALLY IMMEDIATE, FOREIGN KEY (fill_uid) REFERENCES normalized_fills(fill_uid) DEFERRABLE INITIALLY IMMEDIATE, CHECK((length(source_record_fingerprint) = 64)));
CREATE TABLE phase1_journal_snapshot_history_revision_episodes(revision_uid VARCHAR, episode_uid VARCHAR, source_broker VARCHAR NOT NULL, source_account_id VARCHAR NOT NULL, primary_symbol VARCHAR NOT NULL, asset_class VARCHAR NOT NULL, strategy_type VARCHAR NOT NULL, strategy_label VARCHAR NOT NULL, opened_at TIMESTAMP NOT NULL, status VARCHAR NOT NULL, fill_count INTEGER NOT NULL, leg_count INTEGER NOT NULL, leg_summary VARCHAR, cashflow_label VARCHAR, net_quantity DECIMAL(38,10), gross_cashflow DECIMAL(38,10), commission DECIMAL(38,10), fees DECIMAL(38,10), updated_at TIMESTAMP NOT NULL, scope_uid VARCHAR NOT NULL, materialization_lifecycle_quality VARCHAR NOT NULL, materialization_reason_code VARCHAR, lifecycle_quality VARCHAR NOT NULL, reason_code VARCHAR, source_fill_count INTEGER NOT NULL, episode_fingerprint VARCHAR NOT NULL, instrument_count INTEGER NOT NULL, execution_count INTEGER NOT NULL, lifecycle_sequence INTEGER NOT NULL, lifecycle_count INTEGER NOT NULL, instrument_summary VARCHAR NOT NULL, episode_projection_fingerprint VARCHAR NOT NULL, prior_status VARCHAR NOT NULL, reconciled_status VARCHAR NOT NULL, position_reconciliation_status VARCHAR NOT NULL, matched_terminal_event_count INTEGER NOT NULL, state_fingerprint VARCHAR NOT NULL, PRIMARY KEY(revision_uid, episode_uid), FOREIGN KEY (revision_uid) REFERENCES phase1_journal_snapshot_history_revisions(revision_uid) DEFERRABLE INITIALLY IMMEDIATE, CHECK((status IN ('open', 'closed', 'review_required'))), CHECK((prior_status IN ('open', 'closed', 'review_required'))), CHECK((reconciled_status IN ('open', 'closed', 'review_required'))), CHECK((materialization_lifecycle_quality IN ('resolved', 'review_required'))), CHECK((lifecycle_quality IN ('resolved', 'review_required'))), CHECK(((fill_count > 0) AND (leg_count > 0) AND (source_fill_count = fill_count) AND (instrument_count > 0) AND (execution_count = fill_count) AND (lifecycle_sequence > 0) AND (lifecycle_count >= lifecycle_sequence))), CHECK(((length(episode_fingerprint) = 64) AND (length(episode_projection_fingerprint) = 64) AND (length(state_fingerprint) = 64))));
CREATE TABLE phase1_journal_materialized_episode_fills(materialization_uid VARCHAR, episode_uid VARCHAR, leg_index INTEGER, fill_uid VARCHAR NOT NULL, PRIMARY KEY(materialization_uid, episode_uid, leg_index), UNIQUE(materialization_uid, fill_uid), FOREIGN KEY (materialization_uid, episode_uid) REFERENCES phase1_journal_materialized_episodes(materialization_uid, episode_uid) DEFERRABLE INITIALLY IMMEDIATE, FOREIGN KEY (materialization_uid, fill_uid) REFERENCES phase1_journal_materialized_fills(materialization_uid, fill_uid) DEFERRABLE INITIALLY IMMEDIATE, CHECK((leg_index > 0)));
CREATE TABLE phase1_journal_projected_episodes(projection_uid VARCHAR, episode_uid VARCHAR UNIQUE, strategy_type VARCHAR NOT NULL, strategy_label VARCHAR NOT NULL, instrument_count INTEGER NOT NULL, execution_count INTEGER NOT NULL, lifecycle_sequence INTEGER NOT NULL, lifecycle_count INTEGER NOT NULL, instrument_summary VARCHAR NOT NULL, episode_projection_fingerprint VARCHAR NOT NULL, PRIMARY KEY(projection_uid, episode_uid), FOREIGN KEY (projection_uid) REFERENCES phase1_journal_execution_projection_runs(projection_uid) DEFERRABLE INITIALLY IMMEDIATE, FOREIGN KEY (episode_uid) REFERENCES trade_episodes(episode_uid) DEFERRABLE INITIALLY IMMEDIATE, CHECK(((instrument_count > 0) AND (execution_count > 0) AND (lifecycle_sequence > 0) AND (lifecycle_count >= lifecycle_sequence))), CHECK((length(episode_projection_fingerprint) = 64)));
CREATE TABLE phase1_journal_snapshot_history_revision_episode_fills(revision_uid VARCHAR, episode_uid VARCHAR, leg_index INTEGER, fill_uid VARCHAR NOT NULL, source_record_fingerprint VARCHAR NOT NULL, PRIMARY KEY(revision_uid, episode_uid, leg_index), UNIQUE(revision_uid, fill_uid), FOREIGN KEY (revision_uid, episode_uid) REFERENCES phase1_journal_snapshot_history_revision_episodes(revision_uid, episode_uid) DEFERRABLE INITIALLY IMMEDIATE, FOREIGN KEY (fill_uid) REFERENCES normalized_fills(fill_uid) DEFERRABLE INITIALLY IMMEDIATE, CHECK(((leg_index > 0) AND (length(source_record_fingerprint) = 64))));
CREATE TABLE phase1_journal_snapshot_history_revision_executions(revision_uid VARCHAR, episode_uid VARCHAR, execution_index INTEGER, execution_uid VARCHAR NOT NULL, fill_uid VARCHAR NOT NULL, instrument_uid VARCHAR NOT NULL, filled_at_utc VARCHAR NOT NULL, side VARCHAR NOT NULL, quantity DECIMAL(38,10) NOT NULL, fill_price DECIMAL(38,10) NOT NULL, multiplier DECIMAL(38,10) NOT NULL, commission DECIMAL(38,10) NOT NULL, fees DECIMAL(38,10) NOT NULL, currency VARCHAR NOT NULL, schwab_net_cash_movement DECIMAL(38,10) NOT NULL, calculated_net_cash_movement DECIMAL(38,10) NOT NULL, net_amount_reconciled BOOLEAN NOT NULL, execution_projection_fingerprint VARCHAR NOT NULL, PRIMARY KEY(revision_uid, episode_uid, execution_index), UNIQUE(revision_uid, fill_uid), FOREIGN KEY (revision_uid, episode_uid) REFERENCES phase1_journal_snapshot_history_revision_episodes(revision_uid, episode_uid) DEFERRABLE INITIALLY IMMEDIATE, FOREIGN KEY (fill_uid) REFERENCES normalized_fills(fill_uid) DEFERRABLE INITIALLY IMMEDIATE, CHECK(((execution_index > 0) AND (quantity > 0) AND (multiplier > 0))), CHECK(((net_amount_reconciled = CAST('t' AS BOOLEAN)) AND (schwab_net_cash_movement = calculated_net_cash_movement))), CHECK((length(execution_projection_fingerprint) = 64)));
CREATE TABLE phase1_journal_snapshot_history_revision_instruments(revision_uid VARCHAR, episode_uid VARCHAR, instrument_index INTEGER, instrument_uid VARCHAR NOT NULL, asset_class VARCHAR NOT NULL, symbol VARCHAR NOT NULL, underlying_symbol VARCHAR, option_type VARCHAR, expiry DATE, strike DECIMAL(38,10), multiplier DECIMAL(38,10), currency VARCHAR NOT NULL, opening_direction VARCHAR, execution_count INTEGER NOT NULL, buy_quantity DECIMAL(38,10) NOT NULL, sell_quantity DECIMAL(38,10) NOT NULL, captured_quantity_delta DECIMAL(38,10) NOT NULL, instrument_projection_fingerprint VARCHAR NOT NULL, PRIMARY KEY(revision_uid, episode_uid, instrument_index), UNIQUE(revision_uid, episode_uid, instrument_uid), FOREIGN KEY (revision_uid, episode_uid) REFERENCES phase1_journal_snapshot_history_revision_episodes(revision_uid, episode_uid) DEFERRABLE INITIALLY IMMEDIATE, CHECK(((instrument_index > 0) AND (execution_count > 0))), CHECK(((opening_direction IS NULL) OR (opening_direction IN ('LONG', 'SHORT')))), CHECK((length(instrument_projection_fingerprint) = 64)));
CREATE TABLE phase1_journal_projected_executions(projection_uid VARCHAR, episode_uid VARCHAR, execution_index INTEGER, execution_uid VARCHAR NOT NULL UNIQUE, fill_uid VARCHAR NOT NULL UNIQUE, instrument_uid VARCHAR NOT NULL, filled_at_utc VARCHAR NOT NULL, side VARCHAR NOT NULL, quantity DECIMAL(38,10) NOT NULL, fill_price DECIMAL(38,10) NOT NULL, multiplier DECIMAL(38,10) NOT NULL, commission DECIMAL(38,10) NOT NULL, fees DECIMAL(38,10) NOT NULL, currency VARCHAR NOT NULL, schwab_net_cash_movement DECIMAL(38,10) NOT NULL, calculated_net_cash_movement DECIMAL(38,10) NOT NULL, net_amount_reconciled BOOLEAN NOT NULL, execution_projection_fingerprint VARCHAR NOT NULL, PRIMARY KEY(projection_uid, episode_uid, execution_index), FOREIGN KEY (projection_uid, episode_uid) REFERENCES phase1_journal_projected_episodes(projection_uid, episode_uid) DEFERRABLE INITIALLY IMMEDIATE, FOREIGN KEY (fill_uid) REFERENCES normalized_fills(fill_uid) DEFERRABLE INITIALLY IMMEDIATE, CHECK(((execution_index > 0) AND (quantity > 0) AND (multiplier > 0))), CHECK(((net_amount_reconciled = CAST('t' AS BOOLEAN)) AND (schwab_net_cash_movement = calculated_net_cash_movement))), CHECK((length(execution_projection_fingerprint) = 64)));
CREATE TABLE phase1_journal_projected_instruments(projection_uid VARCHAR, episode_uid VARCHAR, instrument_index INTEGER, instrument_uid VARCHAR NOT NULL, asset_class VARCHAR NOT NULL, symbol VARCHAR NOT NULL, underlying_symbol VARCHAR, option_type VARCHAR, expiry DATE, strike DECIMAL(38,10), multiplier DECIMAL(38,10), currency VARCHAR NOT NULL, opening_direction VARCHAR, execution_count INTEGER NOT NULL, buy_quantity DECIMAL(38,10) NOT NULL, sell_quantity DECIMAL(38,10) NOT NULL, captured_quantity_delta DECIMAL(38,10) NOT NULL, instrument_projection_fingerprint VARCHAR NOT NULL, PRIMARY KEY(projection_uid, episode_uid, instrument_index), UNIQUE(projection_uid, episode_uid, instrument_uid), FOREIGN KEY (projection_uid, episode_uid) REFERENCES phase1_journal_projected_episodes(projection_uid, episode_uid) DEFERRABLE INITIALLY IMMEDIATE, CHECK(((instrument_index > 0) AND (execution_count > 0))), CHECK(((opening_direction IS NULL) OR (opening_direction IN ('LONG', 'SHORT')))), CHECK((length(instrument_projection_fingerprint) = 64)));
CREATE VIEW phase1_journal_all_history_revisions AS
SELECT *, CAST(NULL AS VARCHAR) AS snapshot_cutoff_utc FROM phase1_journal_history_revisions
UNION ALL SELECT * FROM phase1_journal_snapshot_history_revisions;

CREATE VIEW phase1_journal_all_history_revision_episodes AS
SELECT * FROM phase1_journal_history_revision_episodes
UNION ALL SELECT * FROM phase1_journal_snapshot_history_revision_episodes;

CREATE VIEW phase1_journal_all_history_revision_episode_fills AS
SELECT * FROM phase1_journal_history_revision_episode_fills
UNION ALL SELECT * FROM phase1_journal_snapshot_history_revision_episode_fills;

CREATE VIEW phase1_journal_all_history_revision_instruments AS
SELECT * FROM phase1_journal_history_revision_instruments
UNION ALL SELECT * FROM phase1_journal_snapshot_history_revision_instruments;

CREATE VIEW phase1_journal_all_history_revision_executions AS
SELECT * FROM phase1_journal_history_revision_executions
UNION ALL SELECT * FROM phase1_journal_snapshot_history_revision_executions;

CREATE VIEW phase1_journal_all_history_activations AS
SELECT * FROM phase1_journal_history_revision_activations
UNION ALL SELECT * FROM phase1_journal_snapshot_history_activations;

CREATE OR REPLACE VIEW phase1_journal_current_revision_ids AS
SELECT source_broker, source_account_id, revision_uid, activation_uid,
       activation_sequence, activated_at
FROM (
    SELECT a.*, ROW_NUMBER() OVER (
        PARTITION BY source_broker, source_account_id
        ORDER BY activation_sequence DESC, activated_at DESC, activation_uid DESC
    ) AS row_num
    FROM phase1_journal_all_history_activations a
) ranked
WHERE row_num = 1;

CREATE OR REPLACE VIEW journal_current_trade_episodes AS
SELECT e.episode_uid, e.source_broker, e.source_account_id, e.primary_symbol,
       e.asset_class, e.strategy_type, e.strategy_label, e.opened_at, e.status,
       e.fill_count, e.leg_count, e.leg_summary, e.cashflow_label,
       e.net_quantity, e.gross_cashflow, e.commission, e.fees, e.updated_at
FROM phase1_journal_all_history_revision_episodes e
JOIN phase1_journal_current_revision_ids c USING (revision_uid)
UNION ALL
SELECT e.* FROM trade_episodes e
WHERE NOT EXISTS (
    SELECT 1 FROM phase1_journal_current_revision_ids c
    WHERE c.source_broker = e.source_broker
      AND c.source_account_id = e.source_account_id
);

CREATE OR REPLACE VIEW journal_current_materialized_episodes AS
SELECT r.materialization_uid, e.episode_uid, e.scope_uid,
       e.materialization_lifecycle_quality AS lifecycle_quality,
       e.materialization_reason_code AS reason_code,
       e.source_fill_count, e.episode_fingerprint
FROM phase1_journal_all_history_revision_episodes e
JOIN phase1_journal_current_revision_ids c USING (revision_uid)
JOIN phase1_journal_all_history_revisions r USING (revision_uid)
UNION ALL
SELECT m.* FROM phase1_journal_materialized_episodes m
JOIN trade_episodes e USING (episode_uid)
WHERE NOT EXISTS (
    SELECT 1 FROM phase1_journal_current_revision_ids c
    WHERE c.source_broker = e.source_broker
      AND c.source_account_id = e.source_account_id
);

CREATE OR REPLACE VIEW journal_current_materialized_episode_fills AS
SELECT r.materialization_uid, x.episode_uid, x.leg_index, x.fill_uid
FROM phase1_journal_all_history_revision_episode_fills x
JOIN phase1_journal_current_revision_ids c USING (revision_uid)
JOIN phase1_journal_all_history_revisions r USING (revision_uid)
UNION ALL
SELECT x.* FROM phase1_journal_materialized_episode_fills x
JOIN trade_episodes e USING (episode_uid)
WHERE NOT EXISTS (
    SELECT 1 FROM phase1_journal_current_revision_ids c
    WHERE c.source_broker = e.source_broker
      AND c.source_account_id = e.source_account_id
);

CREATE OR REPLACE VIEW journal_current_projected_episodes AS
SELECT r.projection_uid, e.episode_uid, e.strategy_type, e.strategy_label,
       e.instrument_count, e.execution_count, e.lifecycle_sequence,
       e.lifecycle_count, e.instrument_summary,
       e.episode_projection_fingerprint
FROM phase1_journal_all_history_revision_episodes e
JOIN phase1_journal_current_revision_ids c USING (revision_uid)
JOIN phase1_journal_all_history_revisions r USING (revision_uid)
UNION ALL
SELECT p.* FROM phase1_journal_projected_episodes p
JOIN trade_episodes e USING (episode_uid)
WHERE NOT EXISTS (
    SELECT 1 FROM phase1_journal_current_revision_ids c
    WHERE c.source_broker = e.source_broker
      AND c.source_account_id = e.source_account_id
);

CREATE OR REPLACE VIEW journal_current_projected_instruments AS
SELECT r.projection_uid, i.episode_uid, i.instrument_index, i.instrument_uid,
       i.asset_class, i.symbol, i.underlying_symbol, i.option_type, i.expiry,
       i.strike, i.multiplier, i.currency, i.opening_direction,
       i.execution_count, i.buy_quantity, i.sell_quantity,
       i.captured_quantity_delta, i.instrument_projection_fingerprint
FROM phase1_journal_all_history_revision_instruments i
JOIN phase1_journal_current_revision_ids c USING (revision_uid)
JOIN phase1_journal_all_history_revisions r USING (revision_uid)
UNION ALL
SELECT i.* FROM phase1_journal_projected_instruments i
JOIN trade_episodes e USING (episode_uid)
WHERE NOT EXISTS (
    SELECT 1 FROM phase1_journal_current_revision_ids c
    WHERE c.source_broker = e.source_broker
      AND c.source_account_id = e.source_account_id
);

CREATE OR REPLACE VIEW journal_current_projected_executions AS
SELECT r.projection_uid, x.episode_uid, x.execution_index, x.execution_uid,
       x.fill_uid, x.instrument_uid, x.filled_at_utc, x.side, x.quantity,
       x.fill_price, x.multiplier, x.commission, x.fees, x.currency,
       x.schwab_net_cash_movement, x.calculated_net_cash_movement,
       x.net_amount_reconciled, x.execution_projection_fingerprint
FROM phase1_journal_all_history_revision_executions x
JOIN phase1_journal_current_revision_ids c USING (revision_uid)
JOIN phase1_journal_all_history_revisions r USING (revision_uid)
UNION ALL
SELECT x.* FROM phase1_journal_projected_executions x
JOIN trade_episodes e USING (episode_uid)
WHERE NOT EXISTS (
    SELECT 1 FROM phase1_journal_current_revision_ids c
    WHERE c.source_broker = e.source_broker
      AND c.source_account_id = e.source_account_id
);

CREATE OR REPLACE VIEW journal_current_lifecycle_reconciliation_runs AS
SELECT r.reconciliation_uid,
       'onejournal.phase1-journal-lifecycle-reconciliation.v1' AS contract_version,
       r.assembly_uid, r.materialization_uid AS source_materialization_uid,
       r.source_account_id, r.asof_date, r.episode_count, r.closed_count,
       r.open_count, r.review_required_count, r.terminal_event_count,
       r.terminal_event_leg_count, r.matched_terminal_event_leg_count,
       r.lifecycle_final_status AS final_status,
       r.reconciliation_result_fingerprint AS result_fingerprint,
       r.created_at AS reconciled_at
FROM phase1_journal_all_history_revisions r
JOIN phase1_journal_current_revision_ids c USING (revision_uid)
UNION ALL
SELECT r.* FROM phase1_journal_lifecycle_reconciliation_runs r
WHERE NOT EXISTS (
    SELECT 1 FROM phase1_journal_current_revision_ids c
    WHERE c.source_broker = 'schwab'
      AND c.source_account_id = r.source_account_id
);

CREATE OR REPLACE VIEW journal_current_episode_lifecycle_states AS
SELECT r.reconciliation_uid, e.episode_uid, e.prior_status,
       e.reconciled_status, e.lifecycle_quality, e.reason_code,
       e.position_reconciliation_status, e.matched_terminal_event_count,
       e.state_fingerprint
FROM phase1_journal_all_history_revision_episodes e
JOIN phase1_journal_current_revision_ids c USING (revision_uid)
JOIN phase1_journal_all_history_revisions r USING (revision_uid)
UNION ALL
SELECT s.* FROM phase1_journal_episode_lifecycle_states s
JOIN trade_episodes e USING (episode_uid)
WHERE NOT EXISTS (
    SELECT 1 FROM phase1_journal_current_revision_ids c
    WHERE c.source_broker = e.source_broker
      AND c.source_account_id = e.source_account_id
);

