CREATE INDEX idx_journal_entry_revisions_episode_uid ON journal_entry_revisions(episode_uid);
CREATE INDEX idx_journal_entry_revisions_strategy_uid ON journal_entry_revisions(strategy_uid);
CREATE INDEX idx_journal_entry_tag_events_entry_uid ON journal_entry_tag_events(entry_uid);
