CREATE INDEX idx_journal_habit_events_date ON journal_habit_events(habit_uid, occurred_on);
CREATE INDEX idx_journal_review_period_events_period ON journal_review_period_events(cadence, period_start, period_end);
CREATE INDEX idx_journal_reviews_episode_uid ON journal_reviews(episode_uid);
