CREATE INDEX idx_normalized_fill_revisions_fill_uid ON normalized_fill_revisions(fill_uid);
CREATE INDEX idx_normalized_lifecycle_event_legs_event ON normalized_lifecycle_event_legs(event_uid);
CREATE INDEX idx_normalized_lifecycle_event_legs_import_run ON normalized_lifecycle_event_legs(import_run_id);
